    err = ROWS(f'<sc-for list="{{{{errors}}}}" as="e" hint-placeholder-count="2"><div style="box-shadow: inset 0 -1px 0 {FILL}"><button type="button" aria-expanded="{{{{e.isOpen}}}}" onClick="{{{{e.toggle}}}}" style="width: 100%; border: 0; background: transparent; color: {INK}; font: inherit; text-align: left; padding: 12px 16px; display: flex; flex-direction: column; gap: 4px">'
               f'<span style="font-family: ui-monospace, Menlo, monospace; font-size: 14px; font-weight: 600">{{{{e.m}}}}</span><span style="font-size: 14px; color: #B3261E; font-weight: 600">{{{{e.c}}}}</span><span style="font-size: 13px; color: {SOFT}">{{{{e.w}}}}</span><span style="font-size: 14px; color: {LINK}; font-weight: 600">Stack trace</span></button>'
               f'<sc-if value="{{{{e.isOpen}}}}" hint-placeholder-val="{{{{false}}}}"><pre style="margin: 0 16px 12px; padding: 10px 12px; border-radius: 10px; background: {FILL}; font-size: 12px; line-height: 1.5; overflow-x: auto">at scheduleNotes (schedule.ts:88)\nat Player.play (use-practice.ts:141)\nat onClick (Transport.tsx:52)</pre></sc-if></div></sc-for>')
    act = ROWS(f'<sc-for list="{{{{activity}}}}" as="a" hint-placeholder-count="4"><div style="min-height: 60px; padding: 8px 16px; display: flex; align-items: center; gap: 12px; box-shadow: inset 0 -1px 0 {FILL}"><span style="flex: 1; display: flex; flex-direction: column; gap: 2px"><span style="font-size: 16px; font-weight: 600">{{{{a.a}}}}</span><span style="{SUB}">{{{{a.w}}}}</span></span><span style="font-size: 13px; color: {SOFT}; white-space: nowrap">{{{{a.d}}}}</span></div></sc-for>')
